type Page = 'home' | 'matches' | 'bracket' | 'factions' | 'gallery' | 'rules' | 'notice' | 'seasons' | 'season-detail' | 'admin' | 'artwork-editor'

const navItems: Array<[Page, string]> = [['home', '首页'], ['matches', '对局中心'], ['bracket', '赛程赛况'], ['factions', '阵营数据'], ['seasons', '历届赛事'], ['gallery', '角色图鉴'], ['rules', '赛制说明'], ['notice', '公告']]
const charactersById = new Map(characters.map((character) => [character.id, character]))

function toDisplayMatch(match: PublicMatch): Match {
  const leftBase = charactersById.get(match.leftId)
  const rightBase = charactersById.get(match.rightId)
  if (!leftBase || !rightBase) throw new Error('公开对局包含未知角色')
  const left=withArtworkKeys({...leftBase,name:match.leftName,game:match.leftGame as Character['game']},{matchArtworkKey:match.leftArtworkKey})
  const right=withArtworkKeys({...rightBase,name:match.rightName,game:match.rightGame as Character['game']},{matchArtworkKey:match.rightArtworkKey})
  return { id:match.id, group:match.groupCode ?? '淘汰', round:match.roundNumber, left, right, leftVotes:match.leftVotes, rightVotes:match.rightVotes, startsAt:match.startsAt, endsAt:match.endsAt, status:match.status === 'live' ? 'live' : match.status === 'closed' ? 'closed' : 'upcoming' }
}

function Artwork({character,compact=false,priority=false}:{character:Character;compact?:boolean;priority?:boolean}) {
  const variant=compact?'match':'gallery'
  const key=artworkKey(character,variant)
  const urls=artworkUrls(key)
  const [sourceIndex,setSourceIndex]=useState(0)
  const hasArtwork=Boolean(variant==='match'?character.matchArtworkKey:character.galleryArtworkKey)||artworkIds.has(character.id)
  useEffect(()=>setSourceIndex(0),[key])
  return <div className={`artwork ${compact?'artwork--compact':''} ${hasArtwork?'artwork--verified':'artwork--pending'}`} style={{'--character-color':character.color} as React.CSSProperties}>
    <span className="artwork__grid"/>
    <span className="artwork__shape artwork__shape--one"/>
    <span className="artwork__shape artwork__shape--two"/>
    {hasArtwork&&sourceIndex<urls.length&&<img className="artwork__image" src={urls[sourceIndex]} alt={`${character.name} 角色立绘`} loading={priority?'eager':'lazy'} fetchPriority={priority?'high':'auto'} decoding="async" onError={()=>setSourceIndex((index)=>index+1)}/>}
    <span className="artwork__copy">{hasArtwork?<>ARTWORK<br/>VERIFIED</>:<>ARTWORK<br/>PENDING</>}</span>
    <span className="artwork__initial">{character.name.slice(0,1)}</span>
    <span className="artwork__hint">{hasArtwork?'已验证立绘':'素材待补全'}</span>
  </div>
}

function Portrait({id,name,avatarArtworkKey,size='standing'}:{id:string;name:string;avatarArtworkKey?:string|null;size?:'standing'|'bracket'|'history'|'champion'}) {
  const urls=portraitArtworkUrls(id,avatarArtworkKey)
  const [sourceIndex,setSourceIndex]=useState(0)
  useEffect(()=>setSourceIndex(0),[id,avatarArtworkKey])
  return <span className={`portrait portrait--${size}`} aria-hidden="true">
    {sourceIndex<urls.length
      ?<img src={urls[sourceIndex]} alt="" loading="lazy" decoding="async" onError={()=>setSourceIndex((index)=>index+1)}/>
      :<b>{name.slice(0,1)}</b>}
  </span>
}

function Countdown({ endsAt }: { endsAt: string }) {
  const [text, setText] = useState('')
  useEffect(() => {
    const update = () => {
      const seconds = Math.max(0, Math.floor((new Date(endsAt).getTime() - Date.now()) / 1000))
      const hours = Math.floor(seconds / 3600)
      const minutes = Math.floor((seconds % 3600) / 60)
      const rest = seconds % 60
      setText(`${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(rest).padStart(2, '0')}`)
    }
    update(); const timer = window.setInterval(update, 1000)
    return () => window.clearInterval(timer)
  }, [endsAt])
  return <span className="countdown">{text}</span>
}

function Header({ page, onNavigate, onLogin, viewer, onLogout }: { page: Page, onNavigate: (page: Page) => void, onLogin: () => void, viewer: Viewer | null, onLogout: () => void }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const canManage = viewer && ['admin','operator'].includes(viewer.role)
  return <header className="site-header">
    <button className="brand" onClick={() => onNavigate('home')} aria-label="返回首页"><span>府</span><b>萌</b><em>2026</em></button>
    <nav className={menuOpen ? 'nav nav--open' : 'nav'}>{navItems.map(([value, label]) => <button key={value} className={page === value ? 'nav__item nav__item--active' : 'nav__item'} onClick={() => { onNavigate(value); setMenuOpen(false) }}>{label}</button>)}{canManage && <button className={page === 'admin' ? 'nav__item nav__item--active' : 'nav__item'} onClick={() => { onNavigate('admin'); setMenuOpen(false) }}>后台管理</button>}</nav>
    <div className="header-actions"><a className="live-link" href="https://live.bilibili.com/21195828" target="_blank" rel="noreferrer"><Play size={15} fill="currentColor" /> 乐府直播间</a>{canManage && <button className="admin-nav-button" onClick={() => onNavigate('admin')}>后台管理</button>}{viewer ? <button className="account-button" onClick={onLogout} aria-label={`${viewer.email}，退出登录`}><UserRound size={17} /><span>{viewer.email}</span><small>退出</small></button> : <button className="login-button" onClick={onLogin}><UserRound size={17} /> 登录投票</button>}<button className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="展开菜单">{menuOpen ? <X /> : <Menu />}</button></div>
  </header>
}

function VoteCard({match,focus=false,onVote,selection,draftCharacterId}:{match:Match;focus?:boolean;onVote:(match:Match,character:Character)=>void;selection?:VoteSelection;draftCharacterId?:string}) {
  const total=match.leftVotes+match.rightVotes
  const leftPercent=total?Math.round(match.leftVotes/total*100):50
  const submitted=selection?.characterId===match.left.id?match.left:selection?.characterId===match.right.id?match.right:null
  const draft=draftCharacterId===match.left.id?match.left:draftCharacterId===match.right.id?match.right:null
  const locked=Boolean(selection)
  const label=(character:Character)=>submitted?.id===character.id?`已投给${character.name}`:locked?`本场已投票，不能再投给${character.name}`:draft?.id===character.id?`取消选择${character.name}`:`投票给${character.name}`
  return <article className={`match-card ${focus?'match-card--focus':''} ${locked?'match-card--voted':draft?'match-card--draft':''}`}>
    <div className="match-card__meta"><span className="group-badge">{match.group} 组 · 第 {match.round} 轮</span>{submitted?<span className="voted-badge"><Check size={14}/> {selection?.riskStatus==='pending'?'选票审核中':'选票已记录'}</span>:draft?<span className="draft-badge"><Check size={14}/> 待提交 · {draft.name}</span>:match.status==='live'?<span className="live-badge"><i/> 投票中</span>:<span className="future-badge">即将开始</span>}</div>
    <div className="duel">
      <button className={draft?.id===match.left.id?'fighter fighter--selected':'fighter'} disabled={locked} onClick={()=>onVote(match,match.left)} aria-label={label(match.left)}><div className="fighter__art"><Artwork character={match.left} compact priority={focus}/>{submitted?.id===match.left.id&&<span className="vote-stamp" aria-label={`我的选票：${match.left.name}`}><b>已投</b><small>MY VOTE</small></span>}</div>{draft?.id===match.left.id&&<span className="fighter__choice"><Check/> 待提交</span>}<span className="fighter__game">{match.left.game}</span><strong>{match.left.name}</strong><small>{match.leftVotes.toLocaleString()} 票</small></button>
      <div className="versus"><span>VS</span>{!locked&&<small>{draft?'已加入清单':match.status==='live'?'实时赛况':'等待开赛'}</small>}</div>
      <button className={draft?.id===match.right.id?'fighter fighter--right fighter--selected':'fighter fighter--right'} disabled={locked} onClick={()=>onVote(match,match.right)} aria-label={label(match.right)}><div className="fighter__art"><Artwork character={match.right} compact priority={focus}/>{submitted?.id===match.right.id&&<span className="vote-stamp" aria-label={`我的选票：${match.right.name}`}><b>已投</b><small>MY VOTE</small></span>}</div>{draft?.id===match.right.id&&<span className="fighter__choice"><Check/> 待提交</span>}<span className="fighter__game">{match.right.game}</span><strong>{match.right.name}</strong><small>{match.rightVotes.toLocaleString()} 票</small></button>
    </div>
    <div className="vote-progress" aria-label={`${match.left.name} ${match.leftVotes} 票，${match.right.name} ${match.rightVotes} 票`}><span className="vote-progress__left" style={{width:`${leftPercent}%`}}/><span className="vote-progress__right" style={{width:`${100-leftPercent}%`}}/></div>
    <footer className="match-card__footer"><span><Clock3 size={15}/> <Countdown endsAt={match.endsAt}/> 后截止</span><small>{submitted?<>我的选择：<b>{submitted.name}</b> · {selection?.riskStatus==='pending'?'审核中':'已锁定'}</>:draft?'可继续选择其他场次后统一提交':match.status==='live'?'点击角色加入待投清单':'等待开赛'}</small></footer>
  </article>
}

function PageTitle({ kicker, title, copy }: { kicker: string, title: string, copy?: string }) {
  return <div className="page-title"><span>{kicker}</span><h1>{title}</h1>{copy && <p>{copy}</p>}</div>
}

function ChampionHero({ season, matches, onNavigate }: { season:PublicSeason;matches:PublicMatch[];onNavigate:(page:Page)=>void }) {
  const result=championResult(season,matches); const base=result?charactersById.get(result.championId):null;const character=base?withArtworkKeys(base,{galleryArtworkKey:season.championArtworkKey}):null
  if(!result||!character)return null
  return <section className="champion-hero"><div className="champion-hero__copy"><p className="eyebrow">FU MOE · {season.name.toUpperCase()} CHAMPION</p><span className="champion-hero__crown"><Trophy/> 冠军诞生</span><h1>{result.championName}</h1><h2>{result.championGame}</h2><p>从 128 位角色中胜出，成为本赛季最终冠军与二游群头像。</p><div className="champion-score"><small>决赛赛果</small><strong>{result.championVotes} : {result.runnerUpVotes}</strong><span>战胜 {result.runnerUpName}</span></div><button className="primary-button" onClick={()=>onNavigate('bracket')}>回顾冠军之路 <ArrowRight/></button></div><div className="champion-hero__art"><Artwork character={character}/><span>CHAMPION</span></div></section>
}

function Home({onNavigate,onVote,liveMatches,matches,rounds,activeRound,season,previousSeason,selections,drafts}:{onNavigate:(page:Page)=>void;onVote:(match:Match,character:Character)=>void;liveMatches:Match[];matches:PublicMatch[];rounds:PublicRound[];activeRound:PublicRound|null;season:PublicSeason|null;previousSeason:PublicSeason|null;selections:Record<string,VoteSelection>;drafts:VoteDrafts}) {
  const roundLabel=activeRound?`${activeRound.stage==='swiss'?'瑞士轮':'淘汰赛'} ${String(activeRound.roundNumber).padStart(2,'0')}`:'等待赛程'; const completed=season?.status==='completed'&&championResult(season,matches)
  if(completed)return <><ChampionHero season={season!} matches={matches} onNavigate={onNavigate}/><section className="section"><div className="section-heading"><div><p className="eyebrow">TOURNAMENT ARCHIVE</p><h2>完整赛季回顾</h2></div><button className="outline-button" onClick={()=>onNavigate('bracket')}>查看签表 <ArrowRight/></button></div><div className="roadmap">{rounds.map((round,index)=><div className="roadmap__item" key={round.id}><span>DAY {index+1} · 已结束</span><b>{round.name}</b><small>{round.roundNumber===4?'冠军加冕':'赛果已归档'}</small></div>)}</div></section></>
  return <><section className="hero"><div className="hero__grid"/><div className="hero__aurora"/><div className="hero__beam hero__beam--one"/><div className="hero__particles"/><div className="hero__copy"><p className="eyebrow">{season?.name??'FU MOE · CHARACTER TOURNAMENT'}</p><h1><span className="hero__line">128 位角色</span><span className="hero__line hero__line--accent">一周决出</span><span className="hero__line">群头像</span></h1><p className="hero__description">每一票，都决定谁将成为二游群头像一个月。</p><div className="hero__actions"><button className="primary-button" onClick={()=>onNavigate('matches')}>进入今日对局 <ArrowRight/></button><button className="text-button" onClick={()=>onNavigate('seasons')}>历届赛事 <ChevronRight/></button></div></div><div className="hero__statboard"><p>{roundLabel}<b>{activeRound?roundStatusLabel(activeRound):'—'}</b></p><div><small>{activeRound?.status==='live'?'距离本轮结束':'下一轮开始时间'}</small>{activeRound?<Countdown endsAt={activeRound.status==='live'?activeRound.endsAt:activeRound.startsAt}/>:season?.startsAt?<Countdown endsAt={season.startsAt}/>:'等待赛程发布'}</div><footer><i/> SERVER TIME · UTC+8</footer></div></section>{season?.status==='published'&&previousSeason?.championName&&<section className="season-transition"><div><p className="eyebrow">DEFENDING CHAMPION</p><h2>{previousSeason.championName}</h2><span>{previousSeason.name} 冠军</span></div><div><p className="eyebrow">NEXT SEASON</p><h2>{season.name}</h2><span>新赛季即将开始</span></div></section>}{season?.status==='live'&&previousSeason?.championName&&<section className="defending-banner"><Trophy/><span>卫冕冠军 · {previousSeason.championName}</span><button onClick={()=>onNavigate('seasons')}>回顾 {previousSeason.name} <ArrowRight/></button></section>}<section className="section section--dark"><div className="section-heading"><div><p className="eyebrow">LIVE MATCHES</p><h2>正在发生的对局</h2><small>本轮共 {liveMatches.length} 场进行中，首页展示 {Math.min(2,liveMatches.length)} 场</small></div>{liveMatches.length>0&&<button className="outline-button" onClick={()=>onNavigate('matches')}>进入对局中心查看全部 <ArrowRight/></button>}</div><div className="match-grid">{liveMatches.slice(0,2).map((match)=><VoteCard key={match.id} match={match} focus onVote={onVote} selection={selections[match.id]} draftCharacterId={drafts[match.id]}/>)}{!liveMatches.length&&<p>当前没有进行中的对局。</p>}</div></section><section className="promise"><div className="promise__mark"><Trophy/></div><div><p className="eyebrow">THE PROMISE</p><h2>最终冠军，将成为二游群头像一个月。</h2></div></section><section className="section"><div className="section-heading"><div><p className="eyebrow">TOURNAMENT MAP</p><h2>七天的晋级之路</h2></div></div><div className="roadmap">{rounds.map((round,index)=><div className={round.status==='live'?'roadmap__item roadmap__item--now':'roadmap__item'} key={round.id}><span>DAY {index+1} · {round.status==='closed'?'已结束':round.status==='live'?'进行中':'待开始'}</span><b>{round.name}</b><small>{round.stage==='swiss'?'8 组同步进行':round.roundNumber===4?'加冕群头像':'单败淘汰'}</small></div>)}</div></section></>
}

function Matches({onVote,matches,activeRound,selections,drafts}:{onVote:(match:Match,character:Character)=>void;matches:Match[];activeRound:PublicRound|null;selections:Record<string,VoteSelection>;drafts:VoteDrafts}) {
  const roundTitle=activeRound?`${activeRound.name} · ${roundStatusLabel(activeRound)}`:'赛程待发布'
  const title=activeRound?.status==='live'?'今日对局':activeRound?.status==='scheduled'?'对阵预告':'本轮赛果'
  return <main className="page"><PageTitle kicker={roundTitle} title={title} copy={activeRound?.status==='live'?'本页仅展示当前进行中的轮次；实时票数仅计入已通过风控的投票。':'本页仅展示当前赛程节点，不与历史轮次混合。'} /><div className="notice-bar"><ShieldCheck size={19}/><span>每个已登录用户，每场仅可投 1 票；投票确认后不可更改。</span></div><div className="match-grid match-grid--full">{matches.map((match)=><VoteCard key={match.id} match={match} onVote={onVote} selection={selections[match.id]} draftCharacterId={drafts[match.id]}/>)}{!matches.length&&<p>暂无已发布对局。</p>}</div></main>
}

function KnockoutTree({ matches, rounds }: { matches:PublicMatch[];rounds:PublicRound[] }) {
  const columns=knockoutColumns(matches,rounds)
  const geometry=bracketGeometry()
  const final=columns.find((column)=>column.round.roundNumber===4)?.matches[0]
  const champion=final?.winnerCharacterId===final?.leftId?final?.leftName:final?.winnerCharacterId===final?.rightId?final?.rightName:null
  if(!columns.length)return <div className="tournament-empty"><Trophy/><div><h2>淘汰赛尚未生成</h2><p>瑞士轮结束后，将按各组排名自动生成 16 强签表。</p></div></div>
  return <section className="bracket-canvas-wrap" aria-label="淘汰赛签表"><p className="bracket-canvas__hint">横向滚动查看完整晋级路径</p><div className="bracket-canvas" style={{width:geometry.width,height:geometry.height}}><svg className="bracket-canvas__lines" viewBox={`0 0 ${geometry.width} ${geometry.height}`} aria-hidden="true"><g>{geometry.paths.map((path,index)=><path d={path} key={index}/>)}</g><path className="bracket-canvas__champion-line" d={geometry.championPath}/></svg>{geometry.rounds.map((layoutRound,roundIndex)=>{const column=columns[roundIndex];return <div key={layoutRound.roundNumber}>{column&&<header className="bracket-canvas__round-title" style={{left:layoutRound.cards[0].x}}><span>ROUND {layoutRound.roundNumber}</span><b>{column.round.name}</b><small>{roundStatusLabel(column.round)}</small></header>}{layoutRound.cards.map((card)=>{const match=column?.matches[card.index];if(!match){const placeholder=knockoutPlaceholder(layoutRound.roundNumber,card.index);return <article className="bracket-canvas__match bracket-canvas__match--placeholder" style={{left:card.x,top:card.y-card.height/2,width:card.width,height:card.height}} key={`placeholder-${layoutRound.roundNumber}-${card.index}`}><div className="bracket-canvas__side"><span><strong>{placeholder.left}</strong><small>{placeholder.leftMeta}</small></span><b className="bracket-canvas__score bracket-canvas__slot">待定</b></div><div className="bracket-canvas__side"><span><strong>{placeholder.right}</strong><small>{placeholder.rightMeta}</small></span><b className="bracket-canvas__score bracket-canvas__slot">待定</b></div><footer>{placeholder.note}</footer></article>}const result=matchResult(match);return <article className="bracket-canvas__match" style={{left:card.x,top:card.y-card.height/2,width:card.width,height:card.height}} key={match.id}><div className={result.winnerId===match.leftId?'bracket-canvas__side bracket-canvas__side--winner':'bracket-canvas__side'}><Portrait id={match.leftId} name={match.leftName} avatarArtworkKey={match.leftAvatarArtworkKey} size="bracket"/><span><strong>{tidyName(match.leftName)}</strong><small>{match.leftGame}</small></span><b className="bracket-canvas__score">{match.leftVotes}</b></div><div className={result.winnerId===match.rightId?'bracket-canvas__side bracket-canvas__side--winner':'bracket-canvas__side'}><Portrait id={match.rightId} name={match.rightName} avatarArtworkKey={match.rightAvatarArtworkKey} size="bracket"/><span><strong>{tidyName(match.rightName)}</strong><small>{match.rightGame}</small></span><b className="bracket-canvas__score">{match.rightVotes}</b></div><footer>{result.label}</footer></article>})}</div>})}<header className="bracket-canvas__round-title bracket-canvas__round-title--winner" style={{left:geometry.champion.x}}><span>WINNER</span><b>冠军</b></header><div className="bracket-canvas__champion" style={{left:geometry.champion.x,top:geometry.champion.y-geometry.champion.height/2,width:geometry.champion.width,height:geometry.champion.height}}>{champion&&final?<Portrait id={final.winnerCharacterId??''} name={champion} avatarArtworkKey={final.winnerCharacterId===final.leftId?final.leftAvatarArtworkKey:final.rightAvatarArtworkKey} size="champion"/>:<Trophy/>}<strong>{champion??'等待决赛'}</strong><small>{champion?'最终胜者':'冠军席位'}</small></div></div></section>
}

function StandingsBoard({ standings }: { standings:PublicStanding[] }) {
  return <><p className="standings-note">实时预估，轮次结束后锁定</p><div className="standings">
    {groupStandings(standings).map(({group,rows})=><section className="standing" key={group}>
      <header><span>{group}</span><b>{group} 组</b><small>{rows.length}/16</small></header>
      {rows.map((row,index)=><div className={index<2?'standing__row standing__row--qualifying':'standing__row'} key={row.id}>
        <em>{index+1}</em>
        <Portrait id={row.id} name={row.name} avatarArtworkKey={row.avatarArtworkKey}/>
        <strong>{tidyName(row.name)}<small>{row.game}</small></strong>
        <span>{row.points} 分<small>对手分 {row.opponentPoints} · 净票差 {row.voteDifference >= 0 ? '+' : ''}{row.voteDifference}</small></span>
      </div>)}{!rows.length&&<p className="standing__empty">本组尚无已结束对局。</p>}</section>)}
  </div></>
}

function formatRoundTime(value:string){return new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date(value))}

function HistoryBoard({matches,rounds}:{matches:PublicMatch[];rounds:PublicRound[]}) {
  const history=historySections(matches,rounds)
  return <section className="match-history">{history.map(({round,matches:roundMatches})=>{const preview=swissRoundPreview(round,matches);return <article className="history-round" key={round.id}><header><div><p className="eyebrow">{round.stage==='swiss'?'SWISS STAGE':'KNOCKOUT STAGE'}</p><h2>{round.name}</h2><small>{formatRoundTime(round.startsAt)} — {formatRoundTime(round.endsAt)}</small></div><span>{roundStatusLabel(round)}</span></header>{roundMatches.length?<div className="history-round__matches">{roundMatches.map((match)=>{const result=matchResult(match);return <div className="history-match" key={match.id}><small>{match.groupCode?`${match.groupCode} 组 · `:''}{result.label}</small><div className="history-match__side"><Portrait id={match.leftId} name={match.leftName} avatarArtworkKey={match.leftAvatarArtworkKey} size="history"/><b className={result.winnerId===match.leftId?'history-match__winner':''}>{tidyName(match.leftName)}</b></div><em>{match.leftVotes}:{match.rightVotes}</em><div className="history-match__side history-match__side--right"><b className={result.winnerId===match.rightId?'history-match__winner':''}>{tidyName(match.rightName)}</b><Portrait id={match.rightId} name={match.rightName} avatarArtworkKey={match.rightAvatarArtworkKey} size="history"/></div></div>})}</div>:preview?<div className="swiss-preview"><p><b>64 场 · 8 组同步进行</b><span>{preview.dependency}</span></p><div>{preview.groups.map(({group,slots})=><section key={group}><header><b>{group} 组</b><small>8 场</small></header>{slots.map((slot)=><div key={slot}><span>对阵 {String(slot).padStart(2,'0')}</span><em>待定</em><i>VS</i><em>待定</em></div>)}</section>)}</div></div>:<p className="history-round__empty">{round.stage==='knockout'?'晋级席位将在前序赛程结算后生成。':'本轮对局将在赛程生成后显示。'}</p>}</article>})}</section>
}

function Bracket({ standings, matches, rounds, initialTab='standings' }: { standings:PublicStanding[];matches:PublicMatch[];rounds:PublicRound[];initialTab?:'standings'|'bracket'|'history' }) {
  const [tab, setTab] = useState<'standings'|'bracket'|'history'>(initialTab)
  return <main className="page"><PageTitle kicker="LIVE TOURNAMENT" title="赛程与赛况" copy="积分依次比较积分、对手分、净票差和预设种子；每组前二晋级 16 强。" /><div className="tabs" role="tablist" aria-label="赛事数据"><button role="tab" aria-selected={tab==='standings'} className={tab==='standings'?'tabs__active':''} onClick={()=>setTab('standings')}>小组积分</button><button role="tab" aria-selected={tab==='bracket'} className={tab==='bracket'?'tabs__active':''} onClick={()=>setTab('bracket')}>淘汰赛签表</button><button role="tab" aria-selected={tab==='history'} className={tab==='history'?'tabs__active':''} onClick={()=>setTab('history')}>对阵历史</button></div>{tab==='bracket'&&<KnockoutTree matches={matches} rounds={rounds}/>} {tab==='standings'&&<StandingsBoard standings={standings}/>} {tab==='history'&&<HistoryBoard matches={matches} rounds={rounds}/>}</main>
}

function FactionLogo({faction,compact=false}:{faction:FactionScore;compact?:boolean}) {
  const brand=factionBrand(faction.name)
  return <div className={compact?'faction-logo faction-logo--compact':'faction-logo'}>{brand.logoPath?<img src={brand.logoPath} alt={`${faction.name} 官方 LOGO`}/>:<b>{faction.name}</b>}</div>
}

function FactionData({matches,roster,season}:{matches:PublicMatch[];roster:Character[];season:PublicSeason|null}) {
  const scoreboard=useMemo(()=>calculateFactionScores(matches,roster.map((character)=>character.game)),[matches,roster])
  const [leader,challenger]=scoreboard.factions
  const duelTotal=(leader?.votes??0)+(challenger?.votes??0)
  const leaderDuelShare=duelTotal?leader.votes/duelTotal*100:50
  const voteGap=Math.abs((leader?.votes??0)-(challenger?.votes??0))
  return <main className="faction-page"><header className="faction-page__header"><p>SEASON FACTION SCORE · LIVE</p><h1>阵营数据</h1><span>{season?.name??'当前赛季'} · 当前赛季共计 {scoreboard.totalVotes.toLocaleString('zh-CN')} 票</span></header>{leader&&challenger?<section className="faction-arena" aria-label="前二阵营对抗"><div className="faction-arena__grid"/><article className="faction-contender faction-contender--leader" style={{'--faction-accent':factionBrand(leader.name).accent} as React.CSSProperties}><span className="faction-contender__rank">RANK 01</span><FactionLogo faction={leader}/><div className="faction-contender__copy"><small>{leader.games.join(' · ')}</small><h2>{leader.name}</h2><strong>{leader.votes.toLocaleString('zh-CN')} 票</strong><b>{leader.share.toFixed(1)}%</b></div></article><div className="faction-versus"><small>TOP FACTION</small><b>VS</b><span>领先 {voteGap.toLocaleString('zh-CN')} 票</span></div><article className="faction-contender faction-contender--challenger" style={{'--faction-accent':factionBrand(challenger.name).accent} as React.CSSProperties}><span className="faction-contender__rank">RANK 02</span><FactionLogo faction={challenger}/><div className="faction-contender__copy"><small>{challenger.games.join(' · ')}</small><h2>{challenger.name}</h2><strong>{challenger.votes.toLocaleString('zh-CN')} 票</strong><b>{challenger.share.toFixed(1)}%</b></div></article><div className="faction-duel-meter" role="meter" aria-label="前二阵营票数对抗" aria-valuenow={leader.votes} aria-valuemin={0} aria-valuemax={duelTotal}><span style={{width:`${leaderDuelShare}%`}}/><i style={{left:`${leaderDuelShare}%`}}/></div></section>:<section className="faction-arena faction-arena--waiting"><b>等待阵营对抗数据</b></section>}<section className="faction-board"><header><div><p>CHASER BOARD</p><h2>追赶者战报</h2></div><span>{scoreboard.factions.length} 个阵营 · 实时累计</span></header><aside className="faction-method"><ShieldCheck size={20}/><div><b>比分按总得票占当前赛季票池比例计算</b><p>同一角色在不同轮次获得的票数均会累计；各阵营参赛角色数量不同，本榜单不做人数归一化。</p></div></aside><div className="faction-chasers">{scoreboard.factions.slice(2).map((faction,index)=><article className="faction-chaser" key={faction.name} style={{'--faction-accent':factionBrand(faction.name).accent} as React.CSSProperties}><em>#{String(index+3).padStart(2,'0')}</em><FactionLogo faction={faction} compact/><div><h3>{faction.name}</h3><small>{faction.games.join(' · ')}</small></div><strong>{faction.votes.toLocaleString('zh-CN')}<small>票</small></strong><b>{faction.share.toFixed(1)}%</b><span><i style={{width:`${faction.share}%`}}/></span></article>)}</div></section></main>
}

function Seasons({ seasons, onOpen }: { seasons:PublicSeason[];onOpen:(slug:string)=>void }) {
  return <main className="page"><PageTitle kicker="TOURNAMENT ARCHIVE" title="历届赛事" copy="每一季都有独立、可分享的赛程档案。"/><div className="season-list">{seasons.map((season)=><button className="season-card" key={season.id} onClick={()=>onOpen(season.slug)}><span>{season.status==='live'?'进行中':season.status==='published'?'即将开始':season.status==='completed'?'已结束':'已归档'}</span><h2>{season.name}</h2>{season.championName?<p><Trophy/> 冠军 · {season.championName}</p>:<p>冠军尚未产生</p>}<small>{season.slug} <ArrowRight/></small></button>)}{!seasons.length&&<p>暂无已发布赛季。</p>}</div></main>
}

function SeasonDetail({ season, matches, rounds, standings, onNavigate }: { season:PublicSeason;matches:PublicMatch[];rounds:PublicRound[];standings:PublicStanding[];onNavigate:(page:Page)=>void }) {
  const result=championResult(season,matches);const championBase=season.championCharacterId?charactersById.get(season.championCharacterId):null;const champion=championBase?withArtworkKeys(championBase,{galleryArtworkKey:season.championArtworkKey}):null
  return <>{result?<ChampionHero season={season} matches={matches} onNavigate={onNavigate}/>:champion&&season.championName?<section className="champion-hero champion-hero--archive"><div className="champion-hero__copy"><p className="eyebrow">FU MOE · {season.name.toUpperCase()}</p><span className="champion-hero__crown"><Trophy/> 历届冠军</span><h1>{season.championName}</h1><h2>{season.championGame}</h2><p>{season.announcement||'本赛季冠军档案已归档。'}</p></div><div className="champion-hero__art"><Artwork character={champion}/><span>CHAMPION</span></div></section>:<section className="season-archive-header"><PageTitle kicker={season.status.toUpperCase()} title={season.name} copy={season.announcement||'完整赛程、积分与淘汰赛赛果归档。'}/></section>}<Bracket standings={standings} matches={matches} rounds={rounds} initialTab="bracket"/></>
}

function Gallery({roster}:{roster:Character[]}) { const [game, setGame] = useState<string>('全部'); const [verifiedOnly, setVerifiedOnly] = useState(false)
  const displayed = useMemo(() => roster.filter((character) => (game === '全部' || character.game === game) && (!verifiedOnly || Boolean(character.galleryArtworkKey)||artworkIds.has(character.id))), [game, roster, verifiedOnly])
  return <main className="page"><PageTitle kicker="128 CONTENDERS" title="角色图鉴" copy={`已自动校验 ${artworkCoverage.verified}/${artworkCoverage.total} 张立绘；未通过质量检查的角色显示素材待补全，不会展示错误图片。`} /><div className="filters">{['全部', ...games].map((item) => <button className={item === game ? 'filters__active' : ''} key={item} onClick={() => setGame(item)}>{item}</button>)}<button className={verifiedOnly ? 'filters__active' : ''} onClick={() => setVerifiedOnly(!verifiedOnly)}>仅已验证立绘</button></div><div className="gallery">{displayed.map((character) => <article className="character-card" key={character.id}><Artwork character={character} /><div><span>{character.game}</span><h3>{character.name}</h3><p>{character.summary}</p><footer><small>{character.group} 组 · 种子 #{character.seed}</small><ChevronRight size={17} /></footer></div></article>)}</div></main> }

function Rules() { const rules = [
  ['01', '128 人参赛', '原神、星穹铁道、绝区零、鸣潮各 16 席；碧蓝航线、蔚蓝档案、FGO、妮姬各 10 席；战双、终末地、异环各 8 席。'],
  ['02', '七日赛程', '前三天为 8 组 × 16 人瑞士制，每天 64 场同步进行；第四日至第七日依次进行 16 强、8 强、半决赛和决赛。每轮持续 24 小时。'],
  ['03', '积分与晋级', '胜 3 分、平 1 分、负 0 分。小组同分依次比较净票差、对手分与预设种子；每组前二晋级。'],
  ['04', '淘汰赛', '16 强起采取单败淘汰。平票时由小组赛积分、对手分、净票差排序较高者晋级。'],
  ['05', '一人一票', '邮箱验证码登录后，每个账户在每场对局中仅可投 1 票；可选择多个场次后统一确认，提交后不可撤回或修改。'],
  ['06', '公平与风控', '发送登录验证码前使用 Turnstile，并结合 IP、设备风险信息、请求限速及人工审计防止刷票。']
] as const
 return <main className="page"><PageTitle kicker="RULEBOOK" title="赛制说明" copy="所有赛程以服务器北京时间为准；客户端倒计时仅供参考。" /><div className="rules">{rules.map(([number, title, content]) => <article key={number}><span>{number}</span><div><h2>{title}</h2><p>{content}</p></div></article>)}</div><aside className="rule-note"><Trophy /><div><b>冠军承诺</b><p>府萌 2026 冠军将成为二游群头像一个月。由群管理员在赛果公布后手动更新。</p></div></aside></main> }

function Notices({ announcement }: { announcement:string }) { return <main className="page"><PageTitle kicker="BULLETIN" title="公告" /><div className="notices">{announcement && <article><time>赛事公告</time><h2>最新公告</h2><p>{announcement}</p></article>}<article><time>2026.07.31</time><h2>府萌 2026 即将开始</h2><p>128 位角色名单、立绘来源和随机分组将在活动开始前公示。活动为非商业化同人赛事。</p></article><article><time>2026.07.31</time><h2>素材与权利说明</h2><p>角色、游戏名称及相关素材权利归各自权利人所有；本站仅使用经核对的官方公开素材。侵权反馈请联系运营。</p></article></div></main> }

function LoginDialog({ onClose, onLoggedIn }: { onClose: () => void; onLoggedIn: (viewer: Viewer) => void }) {
  const [step, setStep] = useState<'email' | 'code'>('email'); const [email, setEmail] = useState(''); const [code, setCode] = useState(''); const [developmentCode, setDevelopmentCode] = useState(''); const [turnstileToken, setTurnstileToken] = useState<string | null>(null); const [turnstileKey, setTurnstileKey] = useState(0); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  const requestCode = async () => { setBusy(true); setError(''); try { const result = await api.requestCode(email, turnstileToken??undefined); setDevelopmentCode(result.developmentCode ?? ''); setCode(result.developmentCode ?? ''); setStep('code') } catch (reason) { setError(reason instanceof Error ? reason.message : '验证码发送失败'); setTurnstileToken(null); setTurnstileKey((key) => key + 1) } finally { setBusy(false) } }
  const verifyCode = async () => { setBusy(true); setError(''); try { const result = await api.verifyCode(email, code); onLoggedIn(result.user); onClose() } catch (reason) { setError(reason instanceof Error ? reason.message : '验证失败') } finally { setBusy(false) } }
  return <div className="dialog-backdrop" role="presentation"><section className="login-dialog" role="dialog" aria-modal="true" aria-labelledby="login-title"><button className="dialog-close" onClick={onClose} aria-label="关闭"><X /></button><p className="eyebrow">SECURE VOTING</p><h2 id="login-title">登录后投票</h2><p>无密码邮箱验证码登录。我们仅以邮箱、IP 与设备风险信息进行身份认证与反刷票。</p>{step === 'code' ? <>{developmentCode && <div className="development-code">本地开发验证码：<b>{developmentCode}</b></div>}<label>6 位验证码<input value={code} onChange={(event) => setCode(event.target.value.replace(/\D/g, '').slice(0, 6))} inputMode="numeric" autoFocus placeholder="000000" /></label><button className="primary-button primary-button--full" disabled={code.length !== 6 || busy} onClick={verifyCode}>{busy ? '正在验证…' : <>完成登录 <ArrowRight /></>}</button><button className="dialog-text-button" disabled={busy} onClick={() => { setStep('email'); setTurnstileToken(null); setTurnstileKey((key) => key + 1) }}>更换邮箱或重新获取验证码</button></> : <><label>邮箱地址<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="name@example.com" /></label><TurnstileWidget onToken={setTurnstileToken} resetKey={turnstileKey} /><button className="primary-button primary-button--full" disabled={!email.includes('@') || !turnstileToken || busy} onClick={requestCode}>{busy ? '正在发送…' : <>发送验证码 <ArrowRight /></>}</button></>}{error && <p className="form-error" role="alert">{error}</p>}<small>同邮箱每天最多发送 5 次；同 IP 每小时最多 10 次。验证码 10 分钟内有效。</small></section></div>
}

type SeasonDialogState = {type:'create'}|{type:'action';season:PublicSeason;action:'publish'|'archive'|'unlock-history'|'lock-history'}

function SeasonOperationDialog({state,seasons,summary,onClose,onCreate,onAction}:{state:SeasonDialogState;seasons:PublicSeason[];summary:ReturnType<typeof seasonRosterSummary>|null;onClose:()=>void;onCreate:(input:{name:string;slug?:string;startsAt:string;copyFromSeasonId?:string;reason:string})=>Promise<void>;onAction:(seasonId:string,action:'publish'|'archive'|'unlock-history'|'lock-history',reason:string)=>Promise<void>}) {
  const [name,setName]=useState('');const [slug,setSlug]=useState('');const [startsAt,setStartsAt]=useState(()=>new Date(Date.now()+7*86_400_000).toISOString().slice(0,16));const [source,setSource]=useState(seasons[0]?.id??'');const [reason,setReason]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  const actionLabel=state.type==='action'?state.action==='publish'?'发布赛季':state.action==='archive'?'归档赛季':state.action==='unlock-history'?'审计解锁':'重新锁定':'创建草稿赛季'
  const submit=async()=>{if(reason.trim().length<5){setError('请填写至少 5 个字符的操作原因');return}setBusy(true);setError('');try{if(state.type==='create'){if(name.trim().length<3)throw new Error('赛季名称至少 3 个字符');const date=new Date(startsAt);if(Number.isNaN(date.getTime()))throw new Error('请选择有效开始时间');await onCreate({name:name.trim(),slug:slug.trim()||undefined,startsAt:date.toISOString(),copyFromSeasonId:source||undefined,reason:reason.trim()})}else await onAction(state.season.id,state.action,reason.trim());onClose()}catch(value){setError(value instanceof Error?value.message:'操作失败')}finally{setBusy(false)}}
  return <div className="dialog-backdrop"><section className="season-dialog" role="dialog" aria-modal="true" aria-labelledby="season-dialog-title"><button className="dialog-close" onClick={onClose} aria-label="关闭"><X/></button><p className="eyebrow">SEASON OPERATION</p><h2 id="season-dialog-title">{actionLabel}</h2>{state.type==='create'?<div className="season-form"><label>赛季名称<input value={name} onChange={(event)=>setName(event.target.value)} placeholder="府萌 2027 夏季赛"/></label><label>固定链接标识（可留空自动生成）<input value={slug} onChange={(event)=>setSlug(event.target.value.toLowerCase().replace(/[^a-z0-9-]/g,''))} placeholder="2027-summer"/></label><label>开始时间<input type="datetime-local" value={startsAt} onChange={(event)=>setStartsAt(event.target.value)}/></label><label>复制名单来源<select value={source} onChange={(event)=>setSource(event.target.value)}>{seasons.map((season)=><option value={season.id} key={season.id}>{season.name}</option>)}</select></label></div>:<><p>你正在对 <b>{state.season.name}</b> 执行“{actionLabel}”。</p>{state.action==='publish'&&summary&&<div className={summary.ready?'roster-readiness roster-readiness--ready':'roster-readiness'}><b>{summary.ready?'名单校验通过':'名单尚未就绪'}</b><span>共 {summary.total}/128 人 · {Object.entries(summary.groupCounts).map(([group,count])=>`${group} ${count}`).join(' · ')}</span>{summary.duplicateSeeds.length>0&&<small>重复种子：{summary.duplicateSeeds.join('、')}</small>}<small>发布后将冻结角色快照和固定链接，并切换唯一当前赛季。</small></div>}{state.action==='archive'&&<p>归档后该赛季将退出当前展示，并保持只读。</p>}{state.action==='unlock-history'&&<p>解锁后管理员可修改历史比分；所有操作仍会写入审计日志。</p>}</>}<label className="season-dialog__reason">操作原因<textarea value={reason} onChange={(event)=>setReason(event.target.value)} placeholder="至少 5 个字符"/></label>{error&&<p className="form-error" role="alert">{error}</p>}<div className="season-dialog__actions"><button onClick={onClose} disabled={busy}>取消</button><button className="primary-button" onClick={()=>void submit()} disabled={busy||(state.type==='action'&&state.action==='publish'&&!summary?.ready)}>{busy?'正在执行…':actionLabel}</button></div></section></div>
}

function SeasonRosterEditor({season,entries,admin,onSave}:{season:PublicSeason;entries:AdminSeasonEntry[];admin:boolean;onSave:(entry:AdminSeasonEntry,next:{groupCode:string;seed:number})=>Promise<void>}) {
  const [term,setTerm]=useState('');const [saving,setSaving]=useState<string|null>(null);const [error,setError]=useState('');const summary=seasonRosterSummary(entries);const editable=admin&&season.status==='draft';const filtered=entries.filter((entry)=>`${entry.name}${entry.game}`.toLowerCase().includes(term.toLowerCase()))
  const update=async(entry:AdminSeasonEntry,next:{groupCode:string;seed:number})=>{setSaving(entry.characterId);setError('');try{await onSave(entry,next)}catch(value){setError(value instanceof Error?value.message:'名单保存失败')}finally{setSaving(null)}}
  return <div className="season-roster"><div className="season-roster__summary"><div><b>{summary.total}/128</b><span>{summary.ready?'发布就绪':'需要调整'}</span></div>{Object.entries(summary.groupCounts).map(([group,count])=><span className={count===16?'season-group-count season-group-count--ready':'season-group-count'} key={group}>{group}组 {count}/16</span>)}</div><div className="season-roster__toolbar"><input aria-label="搜索赛季名单" value={term} onChange={(event)=>setTerm(event.target.value)} placeholder="搜索角色或游戏"/><span>{editable?'草稿名单可编辑':'名单快照只读'}</span></div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="season-roster__groups">{['A','B','C','D','E','F','G','H'].map((group)=><section key={group}><header><b>{group} 组</b><small>{summary.groupCounts[group]}/16</small></header>{filtered.filter((entry)=>entry.groupCode===group).sort((a,b)=>a.seed-b.seed).map((entry)=><div className="season-entry" key={entry.characterId}><strong>{entry.name}<small>{entry.game}</small></strong><label>组<select aria-label={`${entry.name} 分组`} value={entry.groupCode} disabled={!editable||saving===entry.characterId} onChange={(event)=>void update(entry,{groupCode:event.target.value,seed:entry.seed})}>{['A','B','C','D','E','F','G','H'].map((value)=><option key={value}>{value}</option>)}</select></label><label>种子<input aria-label={`${entry.name} 种子`} type="number" min="1" max="128" value={entry.seed} disabled={!editable||saving===entry.characterId} onChange={(event)=>{const seed=Number(event.target.value);if(Number.isInteger(seed)&&seed>=1&&seed<=128)void update(entry,{groupCode:entry.groupCode,seed})}}/></label></div>)}</section>)}</div></div>
}

function Admin({ viewer, onEditCharacter }: { viewer: Viewer | null; onEditCharacter: (id: string) => void }) {
  const [tab, setTab] = useState<'seasons'|'control'|'roster'|'matches'|'risk'|'announcement'|'local'>('seasons')
  const [dashboard, setDashboard] = useState<{pendingVotes:number;activeMatches:number} | null>(null)
  const [tournament, setTournament] = useState<{season:PublicSeason;settings:Record<string,string>;rounds:Array<{id:string;name:string;status:string;startsAt:string;endsAt:string}>;artwork:Array<{status:string;count:number}>}|null>(null)
  const [adminMatches, setAdminMatches] = useState<Array<{id:string;groupCode:string;leftName:string;rightName:string;leftVotes:number;rightVotes:number;status:string}>>([])
  const [risk, setRisk] = useState<Array<{id:string;email:string;matchId:string}>>([])
  const [roster, setRoster] = useState<Array<{id:string;name:string;game:string;summary:string;groupCode:string;seed:number;artworkSourceUrl:string|null;artworkSourceType:string;artworkQualityStatus:string;artworkFocusX:number;artworkFocusY:number}>>([])
  const [announcement,setAnnouncement] = useState('')
  const [adminSeasons,setAdminSeasons] = useState<PublicSeason[]>([])
  const [selectedSeasonId,setSelectedSeasonId] = useState<string>('')
  const [seasonEntries,setSeasonEntries] = useState<AdminSeasonEntry[]>([])
  const [seasonDialog,setSeasonDialog] = useState<SeasonDialogState|null>(null)
  const [message, setMessage] = useState('')
  const load = async () => { try { const [summary,event,matchData,riskData,characterData,seasonData]=await Promise.all([api.dashboard(),api.tournament(),api.adminMatches(),api.riskVotes(),api.characters(),api.adminSeasons()]); setDashboard(summary);setTournament(event);setAnnouncement(event.settings.announcement??'');setAdminMatches(matchData.matches);setRisk(riskData.votes);setRoster(characterData.characters);setAdminSeasons(seasonData.seasons);setSelectedSeasonId((current)=>current||seasonData.seasons.find((season)=>season.status==='draft')?.id||seasonData.seasons[0]?.id||'') } catch (reason) { setMessage(reason instanceof Error ? reason.message : '无法加载后台') } }
  useEffect(() => { if (viewer) void load() }, [viewer])
  useEffect(()=>{if(!selectedSeasonId){setSeasonEntries([]);return}void api.seasonEntries(selectedSeasonId).then((result)=>setSeasonEntries(result.entries)).catch((error)=>setMessage(error instanceof Error?error.message:'无法加载赛季名单'))},[selectedSeasonId])
  if (!viewer) return <main className="page"><PageTitle kicker="ADMIN" title="后台管理" copy="请先使用管理员或运营员账户登录。" /></main>
  if (!['admin','operator'].includes(viewer.role)) return <main className="page"><PageTitle kicker="ACCESS DENIED" title="无后台权限" copy="此账户仅具有投票权限。" /></main>
  const admin = viewer.role === 'admin'
  const control = async (action:'start-now'|'pause'|'resume'|'close'|'publish-schedule'|'lock-roster'|'unlock-roster',roundId?:string) => { const reason=window.prompt('填写操作原因（至少5字）')??''; if(reason.length<5)return; try { await api.controlTournament({action,roundId,reason}); setMessage('赛事控制已执行并写入审计日志。'); await load() } catch(error){setMessage(error instanceof Error?error.message:'操作失败')} }
  const adjust = async (match: typeof adminMatches[number]) => { const reason = window.prompt('填写修正原因（至少 5 个字符）') ?? ''; if (reason.length < 5) return; const leftVotes = Number(window.prompt(`${match.leftName} 当前票数`, String(match.leftVotes))); const rightVotes = Number(window.prompt(`${match.rightName} 当前票数`, String(match.rightVotes))); if (!Number.isInteger(leftVotes) || !Number.isInteger(rightVotes)) return; try { await api.updateMatch(match.id,{leftVotes,rightVotes,reason}); setMessage('比分已修正并写入审计日志。'); await load() } catch (error) { setMessage(error instanceof Error ? error.message : '修正失败') } }
  const publishAnnouncement = async () => { const reason=window.prompt('填写发布原因（至少5字）')??''; if(reason.length<5)return; try { await api.updateSetting('announcement',announcement,reason); setMessage('公告已发布并写入审计日志。'); await load() } catch(error) { setMessage(error instanceof Error?error.message:'公告发布失败') } }
  const createSeason=async(input:{name:string;slug?:string;startsAt:string;copyFromSeasonId?:string;reason:string})=>{const result=await api.createSeason(input);setMessage('草稿赛季已从上一季名单创建。');await load();setSelectedSeasonId(result.seasonId)}
  const actOnSeason=async(seasonId:string,action:'publish'|'archive'|'unlock-history'|'lock-history',reason:string)=>{await api.seasonAction(seasonId,action,reason);setMessage('赛季状态已更新并写入审计日志。');await load()}
  const saveSeasonEntry=async(entry:AdminSeasonEntry,next:{groupCode:string;seed:number})=>{await api.updateSeasonEntry(selectedSeasonId,entry.characterId,{...next,reason:'后台调整赛季名单'});setSeasonEntries((current)=>current.map((item)=>item.characterId===entry.characterId?{...item,...next}:item))}
  const selectedSeason=adminSeasons.find((season)=>season.id===selectedSeasonId)??null
  const selectedSummary=selectedSeason?seasonRosterSummary(seasonEntries):null
  return <main className="page"><PageTitle kicker={`ADMIN · ${viewer.role.toUpperCase()}`} title="后台管理" copy="赛事控制、角色与素材、赛程、风控、审计均会随生产环境上线；测试数据工具仅本地可用。" />{message && <div className="notice-bar">{message}</div>}<div className="admin-stats"><article><small>进行中对局</small><b>{dashboard?.activeMatches ?? '—'}</b></article><article><small>待审核异常票</small><b>{dashboard?.pendingVotes ?? '—'}</b></article><article><small>立绘已验证</small><b>{tournament?.artwork.find((item)=>item.status==='verified')?.count ?? 0}/128</b></article></div><div className="tabs admin-tabs">{([['seasons','赛季管理'],['control','赛事控制'],['roster','角色与素材'],['matches','对局赛程'],['risk','风控队列'],['announcement','公告编辑'],['local','本地测试']] as const).map(([value,label])=><button key={value} className={tab===value?'tabs__active':''} onClick={()=>setTab(value)}>{label}</button>)}</div>{tab==='seasons'&&<section className="admin-panel"><div className="section-heading"><div><h2>赛季管理</h2><p>同一时间仅有一个当前赛季；发布后固定链接与名单快照将被锁定。</p></div>{admin&&<button className="primary-button" onClick={()=>setSeasonDialog({type:'create'})}>复制上一季创建</button>}</div><div className="season-admin-layout"><aside className="season-admin-list">{adminSeasons.map((season)=><button className={season.id===selectedSeasonId?'season-admin-card season-admin-card--active':'season-admin-card'} key={season.id} onClick={()=>setSelectedSeasonId(season.id)}><span>{season.status}{season.isCurrent?' · 当前':''}</span><b>{season.name}</b><small>/seasons/{season.slug}</small></button>)}</aside><div className="season-admin-workspace">{selectedSeason?<><header><div><p className="eyebrow">{selectedSeason.status.toUpperCase()}</p><h2>{selectedSeason.name}</h2><small>/seasons/{selectedSeason.slug}</small></div>{admin&&<div className="admin-actions">{selectedSeason.status==='draft'&&<button onClick={()=>setSeasonDialog({type:'action',season:selectedSeason,action:'publish'})}>发布赛季</button>}{selectedSeason.status==='completed'&&<button onClick={()=>setSeasonDialog({type:'action',season:selectedSeason,action:'archive'})}>归档</button>}{['completed','archived'].includes(selectedSeason.status)&&<button onClick={()=>setSeasonDialog({type:'action',season:selectedSeason,action:selectedSeason.historyUnlocked?'lock-history':'unlock-history'})}>{selectedSeason.historyUnlocked?'锁定历史':'审计解锁'}</button>}</div>}</header><SeasonRosterEditor season={selectedSeason} entries={seasonEntries} admin={admin} onSave={saveSeasonEntry}/></>:<p>请选择赛季。</p>}</div></div></section>}{tab==='control'&&<section className="admin-panel"><h2>赛事状态：{tournament?.settings.tournament_status??'—'}</h2><p>名单：{tournament?.settings.roster_locked==='true'?'已锁定':'可编辑'} · 赛程：{tournament?.settings.schedule_mode??'manual'}</p>{admin&&<div className="admin-actions"><button onClick={()=>void control('lock-roster')}>锁定名单</button><button onClick={()=>void control('unlock-roster')}>解锁名单</button></div>}<h3>轮次控制</h3>{tournament?.rounds.map((round)=><div className="admin-match" key={round.id}><span>{round.status}</span><b>{round.name}</b>{admin&&<div className="admin-actions"><button onClick={()=>void control('start-now',round.id)}>立即开始</button><button onClick={()=>void control('pause',round.id)}>暂停</button><button onClick={()=>void control('close',round.id)}>关闭</button></div>}</div>)}</section>}{tab==='roster'&&<section className="admin-panel"><h2>角色与素材（{roster.length}/128）</h2>{roster.map((character)=><div className="admin-match" key={character.id}><span>{character.game} · {character.artworkQualityStatus}</span><b>{character.name} · {character.groupCode}组 #{character.seed}</b><button onClick={()=>onEditCharacter(character.id)}>打开工作台</button></div>)}</section>}{tab==='matches'&&<section className="admin-panel"><h2>首轮对局</h2>{adminMatches.map((match)=><div className="admin-match" key={match.id}><span>{match.groupCode} 组 · {match.status}</span><b>{match.leftName} <em>{match.leftVotes}:{match.rightVotes}</em> {match.rightName}</b>{admin&&<button onClick={()=>void adjust(match)}>修正比分</button>}</div>)}</section>}{tab==='risk'&&<section className="admin-panel"><h2>风控队列</h2>{risk.length?risk.map((vote)=><div className="admin-match" key={vote.id}><span>{vote.email}</span><b>{vote.matchId}</b>{admin&&<button onClick={async()=>{await api.reviewRiskVote(vote.id,'approve','人工审核通过');await load()}}>通过</button>}</div>):<p>没有待审核异常票。</p>}</section>}{tab==='announcement'&&<section className="admin-panel"><h2>公告编辑</h2>{admin?<><label className="admin-textarea">公告内容<textarea value={announcement} onChange={(event)=>setAnnouncement(event.target.value)} placeholder="输入将在公开公告页置顶显示的内容" /></label><div className="admin-actions"><button className="primary-button" onClick={()=>void publishAnnouncement()}>发布全站公告</button>{tournament?.season&&<button className="primary-button" onClick={async()=>{const reason=window.prompt('填写发布原因（至少5字）')??'';if(reason.length<5)return;await api.updateSeason(tournament.season.id,{announcement,reason});await load()}}>发布当季公告</button>}</div></>:<p>仅管理员可编辑公告。</p>}</section>}{tab==='local'&&<section className="admin-panel"><h2>本地测试工具</h2><p>以下操作在生产环境不可用。</p>{admin&&<div className="admin-actions"><button onClick={async()=>{await api.localData('clear-votes','本地清空投票');await load()}}>清空全部票数</button><button onClick={async()=>{await api.localData('simulate-round','本地模拟轮次');await load()}}>模拟本轮票数</button></div>}</section>}{seasonDialog&&<SeasonOperationDialog state={seasonDialog} seasons={adminSeasons} summary={seasonDialog.type==='action'&&seasonDialog.action==='publish'&&seasonDialog.season.id===selectedSeasonId?selectedSummary:null} onClose={()=>setSeasonDialog(null)} onCreate={createSeason} onAction={actOnSeason}/>}</main>
}

function VoteDialog({choices,matches,onClose,onCompleted}:{choices:Array<{matchId:string;characterId:string}>;matches:Match[];onClose:()=>void;onCompleted:(votes:VoteResult[])=>void}) {
  const [confirmed,setConfirmed]=useState(false);const [message,setMessage]=useState('');const [busy,setBusy]=useState(false)
  const rows=choices.flatMap((choice)=>{const match=matches.find((item)=>item.id===choice.matchId);const character=match?.left.id===choice.characterId?match.left:match?.right.id===choice.characterId?match.right:null;return match&&character?[{match,character}]:[]})
  const submit=async()=>{setBusy(true);setMessage('');try{const result=await api.vote(choices,browserFingerprint());onCompleted(result.votes)}catch(error){setMessage(error instanceof Error?error.message:'投票失败');setBusy(false)}}
  return <div className="dialog-backdrop"><section className="login-dialog vote-dialog" role="dialog" aria-modal="true" aria-labelledby="vote-dialog-title"><button className="dialog-close" onClick={onClose} aria-label="关闭"><X/></button><p className="eyebrow">VOTE CONFIRMATION</p><h2 id="vote-dialog-title">确认 {rows.length} 场投票</h2><p>以下选择将一次提交。每场只能投一次，提交后不可撤回或更改。</p><div className="vote-confirm-list">{rows.map(({match,character})=><article key={match.id}><span>{match.group} 组 · 第 {match.round} 轮</span><b>{character.name}</b><small>{character.game}</small></article>)}</div><label className="confirm-check"><input type="checkbox" checked={confirmed} onChange={(event)=>setConfirmed(event.target.checked)}/> 我已确认以上 {rows.length} 场选择</label><button className="primary-button primary-button--full" disabled={!confirmed||busy} onClick={()=>void submit()}>{busy?'正在提交…':<>提交 {rows.length} 场投票 <Check/></>}</button>{message&&<p className="form-error">{message}</p>}</section></div>
}

function pageForPath(path:string):Page { if(path==='/admin')return'admin';if(path==='/factions')return'factions';if(path==='/seasons')return'seasons';if(/^\/seasons\/[^/]+$/.test(path))return'season-detail';if(/^\/admin\/characters\/c\d{3}$/.test(path))return'artwork-editor';return'home' }
function pathForPage(page:Page){return page==='admin'?'/admin':page==='factions'?'/factions':page==='seasons'?'/seasons':'/'}

function App() {
 const path=window.location.pathname; const initialId=path.match(/^\/admin\/characters\/(c\d{3})$/)?.[1]??null; const initialSlug=path.match(/^\/seasons\/([^/]+)$/)?.[1]??null
 const [page,setPage]=useState<Page>(()=>pageForPath(path)); const [editingCharacterId,setEditingCharacterId]=useState<string|null>(initialId); const [seasonSlug,setSeasonSlug]=useState<string|null>(initialSlug); const [loginOpen,setLoginOpen]=useState(false); const [viewer,setViewer]=useState<Viewer|null>(()=>readCachedViewer(window.localStorage)); const [voteDrafts,setVoteDrafts]=useState<VoteDrafts>({}); const [pendingLoginVote,setPendingLoginVote]=useState<{match:Match;character:Character}|null>(null); const [voteDialogOpen,setVoteDialogOpen]=useState(false); const [voteSelections,setVoteSelections]=useState<Record<string,VoteSelection>>({}); const [voteNotice,setVoteNotice]=useState(''); const [publicMatches,setPublicMatches]=useState<Match[]>([]); const [publicMatchData,setPublicMatchData]=useState<PublicMatch[]>([]); const [publicRounds,setPublicRounds]=useState<PublicRound[]>([]); const [publicStandings,setPublicStandings]=useState<PublicStanding[]>([]); const [publicCharacters,setPublicCharacters]=useState<Character[]>(characters); const [seasons,setSeasons]=useState<PublicSeason[]>([]); const [currentSeason,setCurrentSeason]=useState<PublicSeason|null>(null); const [previousSeason,setPreviousSeason]=useState<PublicSeason|null>(null); const [detailData,setDetailData]=useState<{season:PublicSeason;matches:PublicMatch[];rounds:PublicRound[];standings:PublicStanding[]}|null>(null); const [announcement,setAnnouncement]=useState('')
 const navigate=(next:Page)=>{window.history.pushState({},'',pathForPage(next));setEditingCharacterId(null);setSeasonSlug(null);setPage(next)}
 const openSeason=(slug:string)=>{window.history.pushState({},'',`/seasons/${slug}`);setSeasonSlug(slug);setPage('season-detail')}
 const openEditor=(id:string)=>{window.history.pushState({},'',`/admin/characters/${id}`);setEditingCharacterId(id);setPage('artwork-editor')}
 useEffect(()=>{const onPopState=()=>{const nextPath=window.location.pathname;setEditingCharacterId(nextPath.match(/^\/admin\/characters\/(c\d{3})$/)?.[1]??null);setSeasonSlug(nextPath.match(/^\/seasons\/([^/]+)$/)?.[1]??null);setPage(pageForPath(nextPath))};window.addEventListener('popstate',onPopState);return()=>window.removeEventListener('popstate',onPopState)},[])
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant' as ScrollBehavior})},[page])
 useEffect(()=>{void api.me().then((result)=>{setViewer(result.user);writeCachedViewer(window.localStorage,result.user)}).catch(()=>{})},[])
 useEffect(()=>{if(!viewer){setVoteSelections({});return}void api.myVotes().then((result)=>setVoteSelections(Object.fromEntries(result.votes.map((vote)=>[vote.matchId,vote])))).catch(()=>setVoteSelections({}))},[viewer,currentSeason?.id])
 useEffect(()=>{if(!voteNotice)return;const timer=window.setTimeout(()=>setVoteNotice(''),3500);return()=>window.clearTimeout(timer)},[voteNotice])
 useEffect(()=>{const load=async()=>{await Promise.all([
  api.publicOverview().then((overview)=>{setCurrentSeason(overview.season);setPreviousSeason(overview.previousSeason);setAnnouncement([overview.siteAnnouncement,overview.seasonAnnouncement].filter(Boolean).join('\n\n'))}).catch(()=>{}),
  api.publicMatches().then((result)=>{setPublicMatches(result.matches.map(toDisplayMatch));setPublicMatchData(result.matches)}).catch(()=>{}),
  api.publicRounds().then((result)=>setPublicRounds(result.rounds)).catch(()=>{}),
  api.publicStandings().then((result)=>setPublicStandings(result.standings)).catch(()=>{}),
  api.publicSeasons().then((result)=>setSeasons(result.seasons)).catch(()=>{}),
  api.publicCharacters().then((result)=>setPublicCharacters(result.characters.map((item:PublicCharacter)=>{const base=charactersById.get(item.id);return base?withArtworkKeys({...base,name:item.name,game:item.game as Character['game'],summary:item.summary,group:item.groupCode,seed:item.seed},{galleryArtworkKey:item.galleryArtworkKey,matchArtworkKey:item.matchArtworkKey,avatarArtworkKey:item.avatarArtworkKey}):null}).filter((item):item is Character=>Boolean(item)))).catch(()=>{})
 ])};void load();const timer=window.setInterval(()=>void load(),15_000);return()=>window.clearInterval(timer)},[])
 useEffect(()=>{let active=true;if(!seasonSlug){setDetailData(null);return()=>{active=false}}setDetailData(null);void Promise.all([api.publicSeason(seasonSlug),api.publicMatches(seasonSlug),api.publicRounds(seasonSlug),api.publicStandings(seasonSlug)]).then(([meta,matchData,roundData,standingData])=>{if(active)setDetailData({season:meta.season,matches:matchData.matches,rounds:roundData.rounds,standings:standingData.standings})}).catch(()=>{if(active)setDetailData(null)});return()=>{active=false}},[seasonSlug])
 const openLogin=()=>setLoginOpen(true); const loggedIn=(next:Viewer)=>{setViewer(next);writeCachedViewer(window.localStorage,next);if(pendingLoginVote){setVoteDrafts((current)=>updateVoteDrafts(current,pendingLoginVote.match.id,pendingLoginVote.character.id));setPendingLoginVote(null)}}; const logout=async()=>{await api.logout();setViewer(null);writeCachedViewer(window.localStorage,null);setVoteSelections({});setVoteDrafts({});navigate('home')}; const beginVote=(match:Match,character:Character)=>{if(voteSelections[match.id]||match.status!=='live'||seasonSlug)return;if(!viewer){setPendingLoginVote({match,character});openLogin();return}setVoteDrafts((current)=>updateVoteDrafts(current,match.id,character.id))}; const activeRound=currentRound(publicRounds);const voteChoices=validVoteDrafts(voteDrafts,publicMatchData,voteSelections); const completeVotes=(votes:VoteResult[])=>{const byMatch=new Map(votes.map((vote)=>[vote.selection.matchId,vote]));setVoteSelections((current)=>({...current,...Object.fromEntries(votes.map((vote)=>[vote.selection.matchId,vote.selection]))}));setPublicMatches((current)=>current.map((match)=>{const vote=byMatch.get(match.id);return vote?{...match,...vote.scores}:match}));setPublicMatchData((current)=>current.map((match)=>{const vote=byMatch.get(match.id);return vote?{...match,...vote.scores}:match}));setVoteDrafts((current)=>Object.fromEntries(Object.entries(current).filter(([matchId])=>!byMatch.has(matchId))));void api.publicStandings().then((result)=>setPublicStandings(result.standings)).catch(()=>{});setVoteDialogOpen(false);setVoteNotice(`已提交 ${votes.length} 场投票，选择不可修改。`)}
 const content=page==='home'?<Home onNavigate={navigate} onVote={beginVote} liveMatches={publicMatches.filter((match)=>match.status==='live')} matches={publicMatchData} rounds={publicRounds} activeRound={activeRound} season={currentSeason} previousSeason={previousSeason} selections={voteSelections} drafts={voteDrafts}/>:page==='matches'?<Matches onVote={beginVote} matches={publicMatchData.filter((match)=>match.roundId===activeRound?.id).map(toDisplayMatch)} activeRound={activeRound} selections={voteSelections} drafts={voteDrafts}/>:page==='bracket'?<Bracket standings={publicStandings} matches={publicMatchData} rounds={publicRounds}/>:page==='factions'?<FactionData matches={publicMatchData} roster={publicCharacters} season={currentSeason}/>:page==='seasons'?<Seasons seasons={seasons} onOpen={openSeason}/>:page==='season-detail'&&detailData?<SeasonDetail season={detailData.season} matches={detailData.matches} rounds={detailData.rounds} standings={detailData.standings} onNavigate={navigate}/>:page==='gallery'?<Gallery roster={publicCharacters}/>:page==='rules'?<Rules/>:page==='admin'?<Admin viewer={viewer} onEditCharacter={openEditor}/>:page==='artwork-editor'&&viewer&&editingCharacterId?<ArtworkEditor id={editingCharacterId} viewer={viewer} onBack={()=>navigate('admin')}/>:<Notices announcement={announcement}/>
 return <><Header page={page} onNavigate={navigate} onLogin={openLogin} viewer={viewer} onLogout={()=>void logout()}/>{content}<footer className="site-footer"><button className="brand" onClick={()=>navigate('home')}><span>府</span><b>萌</b><em>SEASONS</em></button><p>{viewer?`${viewer.email} 已登录 · `:''}非商业化同人活动 · 角色及相关素材权利归各权利人所有</p><a href="https://live.bilibili.com/21195828" target="_blank" rel="noreferrer">乐府直播间 <ExternalLink size={14}/></a></footer>{voteChoices.length>0&&<div className="vote-draft-bar" role="region" aria-label="待提交投票"><span>已选 <b>{voteChoices.length}</b> 场</span><button onClick={()=>setVoteDrafts({})}>清空</button><button className="primary-button" onClick={()=>setVoteDialogOpen(true)}>确认提交 {voteChoices.length} 场</button></div>}{voteNotice&&<div className="vote-toast" role="status"><Check/>{voteNotice}</div>}{loginOpen&&<LoginDialog onClose={()=>{setLoginOpen(false);setPendingLoginVote(null)}} onLoggedIn={loggedIn}/>} {voteDialogOpen&&<VoteDialog choices={voteChoices} matches={publicMatches} onClose={()=>setVoteDialogOpen(false)} onCompleted={completeVotes}/>}</>
}

createRoot(document.getElementById('root')!).render(<App />)

export default App
